# Generated by packaging/homebrew/cask.sh in bhumit070/tableplus_rs on each
# release. Edit it there, not here.
cask "tabula" do
  arch arm: "apple-silicon", intel: "intel"

  version "0.1.6"
  sha256 arm:   "c4a074e29db4aeb28a3051e47ccc0023dc0facf6e4d0262b0aa9860aa186ed59",
         intel: "2bd38e7f954f793a77ba88e242c3276cf9259a8fb407fd0b697ca2e793364e19"

  url "https://github.com/bhumit070/tableplus_rs/releases/download/v#{version}/Tabula-#{version}-macos-#{arch}.dmg"
  name "Tabula"
  desc "Database client for PostgreSQL, MySQL, SQLite, Redis and MongoDB"
  homepage "https://bhumit070.github.io/tableplus_rs/"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on macos: :monterey

  app "Tabula.app"

  # Saved passwords live in the login keychain (service "tabula"); zap
  # doesn't touch the keychain.
  zap trash: "~/Library/Application Support/tabula"

  caveats <<~CAVEATS
    Tabula isn't notarized by Apple yet, so macOS blocks the first launch.
    Open Tabula once, then go to System Settings → Privacy & Security and
    click "Open Anyway". Or clear the quarantine flag yourself:
      xattr -dr com.apple.quarantine /Applications/Tabula.app
  CAVEATS
end
